import './style.css';
import { createAppState, createAndAddTodo, addProject } from './app';
import { initDOM } from './dom'
import { addTodoToProject } from './project';
import { loadState, saveState } from './storage.js';

//try loading existing state from localStorage
const myApp = loadState();

//If no saved state is found, initiallize a default configuration
if (!myApp) {
    console.log("No saved state found. Initializing fresh default state...");
    myApp = createAppState();

//Generate seed data (this runs only once on the first load of the app)
createAndAddTodo(myApp, "Default", {
    title: "Finish Odin Project",
    description: "Complete the todo list assignment",
    dueDate: "2026-12-31",
    priority: "high",
    notes:"",
    completed: false
});

//Create a second project an add task to it
addProject(myApp, "Gym Routine");
createAndAddTodo(myApp, "Gym Routine", {
    title: "Leg Day Squats",
    description: "Perform 4 sets of heavy back squats",
    dueDate: "2026-06-30",
    priority: "medium",
    notes: "",
    completed: false
});

// Save this default configuration immediately
saveState(myApp);
} else {
    console.log("Saved state found! Restoring data from localSorage...", myApp)
}

//Connect data state to (loaded or fresh)the UI renderer
initDOM(myApp);