import { createProject, addTodoToProject } from './project.js';
import { createTodo } from './todo.js';

//Factory function to initilize the appliction state
export const createAppState = () => {
    const state = {
        projects: []
    };

    //Initialize with a default project
    const defaultProject = createProject("Default");
    state.projects.push(defaultProject);

    return state;
};

//Functions to manage the overall app state
export const addProject = (appState, name) => {
    const exists = getProjectByName(appState, name);
    if (exists) return null;

    const newProject = createProject(name);
    appState.projects.push(newProject);
    return newProject;
};

export const deleteProject = (appState, name) => {
    if (name ==="Default") return false; //prevent deleting default project

    const index = appState.projects.findIndex(p => p.name === name);
    if (index !== -1) {
        appState.projects.splice(index, 1);
        return true;
    }
    return false;
};

export const getProjectByName = (appState, name) => {
        return appState.projects.find(project => project.name === name);
};

    //Helper fxn to compose and add a todo directly to a project
export const createAndAddTodo = (appState, projectName, todoData) => {
    const project = getProjectByName(appState, projectName);
    if(project) {
        const newTodo = createTodo(
            todoData.title,
            todoData.description,
            todoData.dueDate,
            todoData.priority,
            todoData.notes,
            todoData.completed
        );
        addTodoToProject(project, newTodo);
        return newTodo;
        project.todos.push(todo);
    }
    return null;
};
