const STORAGE_KEY = "odin_todo_list_state";

// saves the entire state object to localStorage
export const saveState = (appState) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(appState));
};

// Loads and parses the state object from localStorage
export const loadState = () => {
    const data = localStorage.getItem(STORAGE_KEY);
    if (data) {
        try {
            return JSON.parse(data);
        } catch (error) {
            console.error("Failed to parse stored localStorage state:", error);
            return null;
        }
    }
    return null; // return null if nothing is saved yet
};