export const createTodo = (title, description, dueDate, priority,notes = "", completed = false) => {
    return {
        title,
        description,
        dueDate,
        priority,
        notes,
        completed
    };
};

//pure-style functions that act upon the todo state
export const toggleTodoComplete = (todo) => {
    todo.completed = !todo.completed;
};

export const updateTodoDetails = (todo, newDetails) => {
    Object.assign(todo, newDetails);
};