import { saveState } from './storage.js';
import { getProjectByName, addProject,createAndAddTodo, deleteProject } from './app.js';
import { toggleTodoComplete, updateTodoDetails } from './todo.js';
import { removeTodoFromProject} from './project.js'

export const initDOM = (appState) => {
    //Keep track of which project is currently active
    let activeProject = getProjectByName(appState, "Default");

    let editingTodo = null; //means we're creating a new one

    //Cache static DOM elements
    const projectListEl = document.getElementById("project-list");
    const activeProjectTitleEl = document.getElementById("active-project-title");
    const todoListEl = document.getElementById("todo-list");

    // Cache project inline form elements
    const addProjectBtn = document.getElementById("add-project-btn");
    const projectFormContainer = document.getElementById("project-form-container");
    const newProjectNameInput = document.getElementById("new-project-name");
    const saveProjectBtn = document.getElementById("save-project-btn");
    const cancelProjectBtn = document.getElementById("cancel-project-btn");


    // Cache task modal form elements
    const addTodoBtn = document.getElementById("add-todo-btn");
    const taskModal = document.getElementById("task-modal");
    const closeModalBtn = document.getElementById("close-modal-btn");
    const taskForm = document.getElementById("task-form");
    const modalHeading = document.querySelector(".modal-content h2");

    // Project Form Toggles
    const showProjectForm = () => {
        projectFormContainer.classList.remove("hidden");
        addProjectBtn.classList.add("hidden");
        newProjectNameInput.focus();
    };

    const hideProjectForm = () => {
        projectFormContainer.classList.add("hidden");
        addProjectBtn.classList.remove("hidden");
        newProjectNameInput.value = "";
    };

    // Task Modal Toggles
    const openTaskModal = () => {
        editingTodo = null; //Reset editing state
        modalHeading.textContent = "Add new task";
        taskModal.classList.remove("hidden");
    }   
    const openEditModal = (todo) => {
        editingTodo = todo; //target the todo to edit
        modalHeading.textContent = "Edit Task";

        // pre-populate fields with existing data
        document.getElementById("task-title").value = todo.title;
        document.getElementById("task-desc").value = todo.description;
        document.getElementById("task-due").vlue = todo.dueDate;
        document.getElementById("task-priority").value = todo.priority;

        taskModal.classList.remove("hidden");
    };

    const closeTaskModal = () => {
        taskModal.classList.add("hidden");
        taskForm.reset();
        editingTodo = null;
    };

    //Render project list in the sidebar
    const renderProjects = () => {
        projectListEl.innerHTML = ""; //clear existing list

        appState.projects.forEach(project => {
            const li = document.createElement("li");
            li.classList.add("project-item");

            //Highlight the active project
            if (project === activeProject) {
                li.classList.add("active");
            }

            //Project name click handler
            const nameSpan = document.createElement("span");
            nameSpan.textContent = project.name;
            nameSpan.addEventListener("click", () => {
                activeProject = project;
                render();
            });

            li.appendChild(nameSpan);

            //append delete button to custom projects only (prevent deleting default)
            if (project.name !== "Default") {
                const deleteProjBtn = document.createElement("button");
                deleteProjBtn.textContent = "x";
                deleteProjBtn.classList.add("delete-project-btn");
                deleteProjBtn.title = "Delete Project";
                //Click event to switch projects
                li.addEventListener("click", () => {
                    activeProject = project;
                    render();
                });

                deleteProjBtn.addEventListener("click", (e) => {
                    e.stopPropagation(); //Stops sidebar active state switching
                    if (confirm(`Delete the project "${project.name} and all of its tasks?`)) {
                        deleteProject(appState, project.name);
                        if(activeProject === project) {
                            activeProject = getProjectByName(appState, "Default");
                        }
                        render();
                    }
                });

                li.appendChild(deleteProjBtn);
            }

            projectListEl.appendChild(li);
        
        });
    };

    //Render todo list for the active project
    const renderTodos = () => {
        activeProjectTitleEl.textContent = activeProject.name;
        todoListEl.innerHTML = ""; //clear existing todos

        if (activeProject.todos.length === 0) {
            todoListEl.innerHTML = "<p class='empty-state'> No tasks here yet.</p>";
            return;
        }
        const todoCardContainer = document.createElement("div");
        activeProject.todos.forEach((todo, index) => {
            const todoCard = document.createElement("div");
            todoCard.classList.add("todo-card", `priority-${todo.priority}`);

            if (todo.completed) {
                todoCard.classList.add("completed");
            }

            //Satatus checkbox
            const checkbox = document.createElement("input");
            checkbox.type = "checkbox";
            checkbox.checked = todo.completed;

            //Listen to checkbox changes, toggle data, & re-render
            checkbox.addEventListener("change", () => {
                toggleTodoComplete(todo);
                render();
            });

            const title = document.createElement("h3");
            title.textContent = todo.title;

            const date = document.createElement("span");
            date.textContent = `Due: ${todo.dueDate}`;
            date.classList.add("due-date");

            //Container for action buttons
            const actionContainer = document.createElement("div");
            actionContainer.classList.add("todo-actions");

            //Edit button
            const editBtn = document.createElement("button");
            editBtn.innerHTML = "✏️";
            editBtn.classList.add("edit-todo-btn");
            editBtn.title = "Edit Task";
            editBtn.addEventListener("click", () => openEditModal(todo));

            //Delete Button
            const deleteBtn = document.createElement("button");
            deleteBtn.innerHTML = "🗑️";
            deleteBtn.classList.add("delete-todo-btn");
            deleteBtn.title = "Delete Task";
            deleteBtn.addEventListener("click", () => {
                if (confirm(`Delete the task "${todo.title}"?`)) {
                    removeTodoFromProject(activeProject, index);
                    render();
                }
            });

            actionContainer.append(editBtn, deleteBtn);
            todoCard.append(checkbox, title, date, actionContainer);
            todoListEl.appendChild(todoCard);

        });
    };

    //Master render function
    const render = () => {
        renderProjects();
        renderTodos();
        saveState(appState); //auto-saves to localStorage whenever the page redraws
    };

    // FORM EVENT  LISTENERS
    //handle project creation
    addProjectBtn.addEventListener("click", showProjectForm);
    cancelProjectBtn.addEventListener("click", hideProjectForm);

    saveProjectBtn.addEventListener("click", () => {
        const name = newProjectNameInput.value.trim();
        if (name) {
            const newProj = addProject(appState, name);
            if (newProj) {
                activeProject = newProj; //auto-select the newly created project
                hideProjectForm();
                render();
            } else {
                alert("A project with that name already exists!");
            }
        }
    });

    // Handle task modal logic
    addTodoBtn.addEventListener("click", openTaskModal);
    closeModalBtn.addEventListener("click", closeTaskModal);

    taskForm.addEventListener("submit", (e) => {
        e.preventDefault(); //Prevents default page on submission

        const title = document.getElementById("task-title").value.trim();
        const description = document.getElementById("task-desc").value.trim();
        const dueDate = document.getElementById("task-due").value;
        const priority = document.getElementById("task-priority").value;

        if (editingTodo) {
            //If we are editing, update the existing object properties in place
            updateTodoDetails(editingTodo, {
                title,
                description,
                dueDate,
                priority
            });
        } else {
            //if we are not editing, append a new todo object instead
            createAndAddTodo(appState, activeProject.name, {
            title,
            description,
            dueDate,
            priority,
            notes: "",
            completed: false
        });
        }

        // Composes and appends the new todo directly to our data state
        
        render();
        closeTaskModal();
    });
    render();
    //Run initial render on startup

};